class Solution {
public:
    vector<bool> findAnswer(int n, vector<vector<int>>& edges) {
        vector<vector<pair<int, int>>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }

        auto dijkstra = [&](int start) {
            vector<long long> dist(n, 1e18);
            dist[start] = 0;
            priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
            pq.push({0, start});
            while (!pq.empty()) {
                auto [d, u] = pq.top();
                pq.pop();
                if (d > dist[u]) continue;
                for (const auto& [v, w] : adj[u]) {
                    if (d + w < dist[v]) {
                        dist[v] = d + w;
                        pq.push({d + w, v});
                    }
                }
            }
            return dist;
        };

        auto dist0 = dijkstra(0);
        auto distN = dijkstra(n - 1);
        long long total = dist0[n - 1];

        if (total >= 1e18) {
            return vector<bool>(edges.size(), false);
        }

        vector<bool> ans;
        for (const auto& e : edges) {
            int u = e[0], v = e[1], w = e[2];
            bool on_path = (dist0[u] + w + distN[v] == total) || (dist0[v] + w + distN[u] == total);
            ans.push_back(on_path);
        }
        return ans;
    }
};

class Solution {
    public boolean[] findAnswer(int n, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }

        long[] dist0 = dijkstra(0, n, adj);
        long[] distN = dijkstra(n - 1, n, adj);
        long total = dist0[n - 1];

        boolean[] ans = new boolean[edges.length];
        if (total >= 1e17) return ans;

        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0], v = edges[i][1], w = edges[i][2];
            if (dist0[u] + w + distN[v] == total || dist0[v] + w + distN[u] == total) {
                ans[i] = true;
            }
        }
        return ans;
    }

    private long[] dijkstra(int start, int n, List<List<int[]>> adj) {
        long[] dist = new long[n];
        Arrays.fill(dist, (long) 1e18);
        dist[start] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.offer(new long[]{0, start});

        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long d = top[0];
            int u = (int) top[1];
            if (d > dist[u]) continue;

            for (int[] edge : adj.get(u)) {
                int v = edge[0], w = edge[1];
                if (d + w < dist[v]) {
                    dist[v] = d + w;
                    pq.offer(new long[]{dist[v], v});
                }
            }
        }
        return dist;
    }
}

var findAnswer = function(n, edges) {
    const adj = Array.from({length: n}, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }

    function dijkstra(start) {
        const dist = new Array(n).fill(Infinity);
        dist[start] = 0;
        const heap = [[0, start]];

        function push(val) {
            heap.push(val);
            let idx = heap.length - 1;
            while (idx > 0) {
                let p = Math.floor((idx - 1) / 2);
                if (heap[idx][0] < heap[p][0]) {
                    [heap[idx], heap[p]] = [heap[p], heap[idx]];
                    idx = p;
                } else break;
            }
        }
        function pop() {
            const top = heap[0];
            const last = heap.pop();
            if (heap.length > 0) {
                heap[0] = last;
                let idx = 0;
                while (true) {
                    let left = 2 * idx + 1, right = 2 * idx + 2, best = idx;
                    if (left < heap.length && heap[left][0] < heap[best][0]) best = left;
                    if (right < heap.length && heap[right][0] < heap[best][0]) best = right;
                    if (best !== idx) {
                        [heap[best], heap[idx]] = [heap[idx], heap[best]];
                        idx = best;
                    } else break;
                }
            }
            return top;
        }

        while (heap.length > 0) {
            const [d, u] = pop();
            if (d > dist[u]) continue;
            for (const [v, w] of adj[u]) {
                if (d + w < dist[v]) {
                    dist[v] = d + w;
                    push([d + w, v]);
                }
            }
        }
        return dist;
    }

    const dist0 = dijkstra(0);
    const distN = dijkstra(n - 1);
    const total = dist0[n - 1];

    if (total === Infinity) {
        return new Array(edges.length).fill(false);
    }

    return edges.map(([u, v, w]) => {
        return (dist0[u] + w + distN[v] === total) || (dist0[v] + w + distN[u] === total);
    });
};
